package main

import (
 "context"; "encoding/json"; "fmt"; "io"; "log"; "log/slog"; "net/http"; "os"; "strconv"; "sync/atomic"; "time"
)
type service struct { requests, failures uint64; failAfter uint64 }
var peerURL string
func (s *service) log(event string, fields ...any) { args := append([]any{"event", event, "service", "agenttrust-worker"}, fields...); slog.Info("worker_event", args...) }
func (s *service) work(w http.ResponseWriter, r *http.Request) { start:=time.Now(); n:=atomic.AddUint64(&s.requests,1); traceID:=r.Header.Get("X-Trace-ID"); if traceID=="" {traceID=r.Header.Get("X-Correlation-ID")}; if traceID=="" {traceID=fmt.Sprintf("worker-%d",n)}; if s.failAfter>0 && n>s.failAfter && n<=s.failAfter+3 {atomic.AddUint64(&s.failures,1); s.log("injected_failure","request_id",n,"trace_id",traceID); w.Header().Set("X-Trace-ID",traceID); http.Error(w,"injected failure",503); return}; latency:=time.Since(start); s.log("request_complete","request_id",n,"trace_id",traceID,"latency_ms",float64(latency.Microseconds())/1000,"gpu_event_source","simulated"); w.Header().Set("Content-Type","application/json"); w.Header().Set("X-Trace-ID",traceID); json.NewEncoder(w).Encode(map[string]any{"ok":true,"request_id":n,"trace_id":traceID,"latency_ms":float64(latency.Microseconds())/1000,"gpu_event_source":"simulated"}) }
func (s *service) health(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(map[string]any{"status":"ok","worker_id":os.Getenv("WORKER_ID"),"requests":atomic.LoadUint64(&s.requests),"failures":atomic.LoadUint64(&s.failures)})}
func (s *service) ready(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(map[string]any{"status":"ready"})}
func (s *service) fanout(w http.ResponseWriter,r *http.Request){if peerURL==""{http.Error(w,"peer not configured",501);return}; req,_:=http.NewRequestWithContext(context.Background(),http.MethodGet,peerURL+"/work",nil); req.Header.Set("X-Trace-ID",r.Header.Get("X-Trace-ID")); req.Header.Set("X-Correlation-ID",r.Header.Get("X-Correlation-ID")); resp,err:=http.DefaultClient.Do(req); if err!=nil{http.Error(w,err.Error(),502);return}; defer resp.Body.Close(); body,_:=io.ReadAll(resp.Body); w.Header().Set("Content-Type","application/json"); w.WriteHeader(resp.StatusCode); w.Write(body)}
func main(){failAfter,_:=strconv.ParseUint(os.Getenv("FAIL_AFTER"),10,64); peerURL=os.Getenv("PEER_URL"); s:=&service{failAfter:failAfter}; mux:=http.NewServeMux(); mux.HandleFunc("/work",s.work); mux.HandleFunc("/healthz",s.health); mux.HandleFunc("/readyz",s.ready); mux.HandleFunc("/fanout",s.fanout); port:=os.Getenv("PORT"); if port==""{port="8080"}; s.log("service_started","port",port,"fail_after",failAfter); if err:=http.ListenAndServe(":"+port,mux);err!=nil{log.Fatal(err)}}
